// You can work here or download the template
const userInput = document.getElementById("userInput");

const submitBtn = document.querySelector("button");

const list = document.querySelector("ul");

submitBtn.addEventListener("click", event => {
  event.preventDefault();

  const userInputValue = userInput.value;
  if (!userInputValue) {
    return;
  }

  const id = self.crypto.randomUUID();
  const item = { id: id, content: userInputValue };

  //retrieves items array from the local storage
  const arrayItems = JSON.parse(localStorage.get("items")) || [];
  arrayItems.push(item);

  //update the localStorage
  localStorage.setItem("items", JSON.stringify(arrayItems));

  //retrieves items array from the local storage
  arrayItems = JSON.parse(localStorage.get("items")) || [];
  //clear list children
  list.textContent = "";

  for (const itemObject of arrayItems) {
    const listItem = document.createElement("li");
    listItem.textContent = itemObject.content;

    const redBtn = document.createElement("button");
    redBtn.textContent = "Delete";

    listItem.appendChild(redBtn);

    list.appendChild(listItem);
  }

  userInputValue.textContent = "";
});
